I was able to write a simple test application for your help. It is written in Delphi, but should still be readable:

```
function GetPasswordCallback(buf: PIdAnsiChar; size: TIdC_INT; rwflag: TIdC_INT; userdata: Pointer): TIdC_INT; cdecl;
begin
  Writeln('size: ', size);
  Result := 0;
end;

procedure Main;
var
  LCtx: PSSL_CTX;
begin
  LCtx := SSL_CTX_new(TLS_method());
  SSL_CTX_set_mode(LCtx, SSL_MODE_AUTO_RETRY);
  SSL_CTX_set_default_verify_paths(LCtx);
  SSL_CTX_set_session_cache_mode(LCtx, SSL_SESS_CACHE_BOTH);
  SSL_CTX_set_default_passwd_cb(LCtx, GetPasswordCallback);

  SSL_CTX_use_certificate_chain_file(LCtx, GetPAnsiChar('C:\server.crt'));
  SSL_CTX_use_PrivateKey_file(LCtx, GetPAnsiChar('C:\server.pem'), SSL_FILETYPE_PEM);
  SSL_CTX_check_private_key(LCtx);
end;
```
`GetPasswordCallback` will be called 2 times. First with `size = 1022`, second time with `size = 1023`.
Both time I excepted `size = 1024`.

Thanks, I translated that into C, and saw the same results.

``` C
#include <openssl/core.h>
#include <openssl/types.h>
#include <openssl/ssl.h>

pem_password_cb GetPasswordCallback;
int GetPasswordCallback(char *buf, int size, int rw_flag, void *userdata)
{
  printf("size: %d\n", size);
  return 0;
}

int main(int argc, char *argv[])
{
  SSL_CTX *LCtx = SSL_CTX_new(TLS_method());
  SSL_CTX_set_mode(LCtx, SSL_MODE_AUTO_RETRY);
  SSL_CTX_set_default_verify_paths(LCtx);
  SSL_CTX_set_session_cache_mode(LCtx, SSL_SESS_CACHE_BOTH);
  SSL_CTX_set_default_passwd_cb(LCtx, GetPasswordCallback);

  SSL_CTX_use_certificate_chain_file(LCtx, "server.crt");
  SSL_CTX_use_PrivateKey_file(LCtx, "server.pem", SSL_FILETYPE_PEM);
  SSL_CTX_check_private_key(LCtx);
}
```

